UPDATE t_amz_product_refresh_type r
LEFT JOIN t_amazon_auth a ON a.id = r.amazonauthid
SET r.refresh_time = NULL
WHERE a.shop_id = #{dto.shopid,jdbcType=CHAR}
  AND r.refresh_time IS NOT NULL

      AND a.groupid = #{dto.groupid,jdbcType=CHAR}


      AND r.pid IN (
          SELECT id FROM t_product_info WHERE marketplaceid = #{dto.marketplaceid,jdbcType=CHAR}
      )


      AND r.type IN

          1
          2
          3



      AND r.pid IN

          #{pid,jdbcType=CHAR}
